using System;
using System.Collections.Generic;
using Godot;
public partial class GameRoot {
    private static readonly Dictionary<string,string> encodedWeights95=new(){
        ["z74_heavy"]="",
        ["z74_cyst"]="",
        ["z74_thin"]="",
        ["z74_eye"]="",
        ["z74_hunch"]="",
        ["z74_flayed"]="",
        ["falciante84"]="",
        ["ossuary"]="",
        ["bell"]="",
        ["stitch"]="",
        ["sexton"]="",
        ["corrupted"]=""
    };
    private const int MeshCols95=25,MeshRows95=33;
    private static readonly int[] indices95=MeshIndices95();
    private static int[] MeshIndices95(){var list=new List<int>();for(int y=0;y<MeshRows95-1;y++)for(int x=0;x<MeshCols95-1;x++){int a=y*MeshCols95+x,b=a+1,c=a+MeshCols95,d=c+1;list.AddRange(new[]{a,b,c,b,d,c});}return list.ToArray();}
    private readonly Dictionary<string,byte[]> weights95=new();
    private readonly Dictionary<string,Texture2D> composite95=new();
    private Texture2D? EnemyComposite95(string k){
        if(battle==null)return null;int mask=0;for(int i=0;i<6;i++)if(battle.Parts[Parts[i]]<=0)mask|=1<<i;
        if(mask==0)return Art("intact82_"+k);string key=k+":"+mask;if(composite95.TryGetValue(key,out var found))return found;
        var src=Art("limb75_"+k+"_0");if(src==null)return null;var im=Godot.Image.CreateEmpty(src.GetWidth(),src.GetHeight(),false,Godot.Image.Format.Rgba8);
        foreach(int i in new[]{4,5,2,3,0,1}){if((mask&(1<<i))!=0)continue;var t=Art("limb75_"+k+"_"+i);if(t==null)continue;var part=t.GetImage();part.Convert(Godot.Image.Format.Rgba8);im.BlendRect(part,new Rect2I(0,0,part.GetWidth(),part.GetHeight()),Vector2I.Zero);}
        found=ImageTexture.CreateFromImage(im);if(composite95.Count>32)composite95.Clear();composite95[key]=found;return found;
    }
    private void DrawEnemyMesh95(string k,Texture2D tex,Rect2 r,Transform2D parent,Vector2[] pivots,float[] angles,Vector2[] offsets,Color tint){
        if(!weights95.TryGetValue(k,out var weights)){weights=Convert.FromBase64String(encodedWeights95[k]);weights95[k]=weights;}
        int n=MeshCols95*MeshRows95;var pts=new Vector2[n];var uv=new Vector2[n];var colors=new Color[n];
        for(int y=0;y<MeshRows95;y++)for(int x=0;x<MeshCols95;x++){
            int i=y*MeshCols95+x;uv[i]=new(x/(float)(MeshCols95-1),y/(float)(MeshRows95-1));Vector2 at=r.Position+uv[i]*r.Size;Vector2 p=Vector2.Zero;float sum=0;
            for(int j=0;j<6;j++){float weight=weights[i*6+j];if((j==2||j==3)&&k!="ossuary"&&k!="bell")weight*=1-Ease95((uv[i].Y-.65f)/.12f);if(j==0&&uv[i].Y>.65f)weight+=22*Ease95((uv[i].Y-.65f)/.15f);if(j==4||j==5){if(uv[i].Y>.71f)weight+=32*Ease95((uv[i].Y-.71f)/.14f)*(j==4?uv[i].X:1-uv[i].X);}p+=(pivots[j]+(at-pivots[j]).Rotated(angles[j])+offsets[j])*weight;sum+=weight;}
            pts[i]=parent*(sum>0?p/sum:at);colors[i]=tint;
        }
        DrawSetTransform(Vector2.Zero);RenderingServer.CanvasItemAddTriangleArray(GetCanvasItem(),indices95,pts,colors,uv,Array.Empty<int>(),Array.Empty<float>(),tex.GetRid());
    }
}
